class BaseCtor { BaseCtor(){ System.out.println("base"); } }
public class ConstructorInvocationDemo extends BaseCtor {
    ConstructorInvocationDemo(){ this(7); }
    ConstructorInvocationDemo(int value){ super(); System.out.println("child=" + value); }
    public static void main(String[] args){ new ConstructorInvocationDemo(); }
}
